insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('a1c13b0e-74a1-57e1-bd4a-9f87c5243e88', 'rg4-story-details-inference-p01', (select id from public.skills where slug = 'read-g4-story-details-inference'), null,
        '3-5', $q$The Fast Part$q$, $q$Tomas had one week to learn his recorder part for the spring concert. The song had a fast part in the middle, and his fingers kept tripping over the notes.

Every afternoon, he practiced in his room with the door closed. His little sister, Rosa, sat outside in the hallway with her coloring book. Sometimes she hummed along.

On Thursday, Tomas tossed his recorder onto the bed. "I can't do the fast part," he said. "I'm going to ask Mr. Okafor if I can just stand in the back and pretend."

That night, he heard a soft tapping from the hallway. Rosa was tapping a crayon on the floor. Tap, tap, tap, tap. It was slow and steady, like a clock.

Tomas picked up his recorder again. He played the fast part very slowly, one note for each tap. Then he played it again, a little faster. Rosa tapped faster too.

By Sunday, his fingers knew the way. At the concert, Tomas played every note. When the song ended, he looked out at the crowd. Rosa was in the front row, tapping her knee and grinning.

After the concert, Tomas gave her the paper program with his name on it. "You should keep this," he said. "Half of it is yours."$q$, 'draft')
