-- Passage rg4-story-details-inference-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('01e3e42a-1a0c-5015-94db-c161f95134c9', 'rg4-story-details-inference-p02', (select id from public.skills where slug = 'read-g4-story-details-inference'), null,
        '3-5', $q$Moving Day$q$, $q$The boxes are stacked by the door in a row.
My room has an echo wherever I go.
The posters are rolled and the shelves are all bare.
My bed is in pieces. I sit on the stair.

I open the closet to check one last time.
I find little pencil marks, line after line.
The first one is low, only up to my knee.
Each mark has a date, and each mark is me.

My dad calls, "The truck is all packed. Time to go!"
I take out a pencil and kneel down low.
Beside the first mark, in my neatest hand, small,
I write, "Hi, new kid. Keep on growing up tall."

I close the door softly and stand there a while.
I wipe off my cheek, but I'm starting to smile.
Somebody new will be measured right here,
And I hope that they grow a whole inch every year.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
