-- Passage rg4-story-details-inference-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('b1952d63-b817-5c15-a1cb-46520fff2361', 'rg4-story-details-inference-p06', (select id from public.skills where slug = 'read-g4-story-details-inference'), null,
        '3-5', $q$The List on the Refrigerator$q$, $q$Jamal's grandmother, Nana Bea, lived three states away. For her birthday, Jamal's family mailed her a tablet so they could see each other on video calls.

The first call did not go well. Jamal could only see the ceiling of Nana Bea's kitchen. "Nana, turn the tablet around!" he said. The screen spun, and now he could see her ear.

The second call was a little better. He could see her whole face, but she had pressed a button that made her look like a cartoon cat. Jamal laughed so hard that he snorted. Nana Bea laughed too, even though she did not know what was funny.

Before the third call, Jamal made a list. He wrote each step in big letters and drew a picture beside it. Step one showed the green button. Step two showed the tablet propped up against a sugar jar. His mom mailed the list the next morning.

A week later, the tablet chimed. Nana Bea's face filled the screen, right in the center. Behind her, taped to the refrigerator, was a sheet of paper with big letters and drawings.

"Look who figured it out," she said, smiling.

Jamal smiled back. He did not tell her that he had spent two hours on that list.$q$, 'draft')
