-- Passage rg4-story-details-inference-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('14e79ed5-2ba2-518b-b231-adcf33e6aef8', 'rg4-story-details-inference-p07', (select id from public.skills where slug = 'read-g4-story-details-inference'), null,
        '3-5', $q$Before Anyone Wakes$q$, $q$The snow fell all night while the whole town was asleep.
By morning, the drifts were all fluffy and deep.
I pulled on my boots and my hat with the bear,
And tiptoed outside in the cold morning air.

Next door is the house of our neighbor, Mrs. Lee.
Her walk was all buried. The snow reached my knee.
She walks with a cane, and she moves very slow.
I thought of her steps on the ice and the snow.

So I picked up our shovel and started to scrape.
I cleared her whole path in a neat little shape.
I salted the steps so they wouldn't be slick,
Then I put the shovel back, quiet and quick.

At breakfast, my mom saw the path, clean and neat.
"Now who did that?" she asked, looking out at the street.
I shrugged and said, "Some kind person, I guess."
And that was the most that I planned to confess.

That afternoon, someone knocked on our door.
A tin full of cookies sat there on the floor.
The note said, "For whoever cleared my walk today."
My mom looked at me, and I looked away.$q$, 'draft')
