-- Passage rg4-theme-summary-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('60380577-c54a-532a-8e39-a499db1f8741', 'rg4-theme-summary-p03', (select id from public.skills where slug = 'read-g4-theme-summary'), null,
        '3-5', $q$The Red Kite$q$, $q$My kite lay flat upon the ground,
a paper bird that made no sound.
I ran and yanked it, hard and fast.
It flipped and flopped and fell at last.

Then Grandpa said, "Stand still and wait.
Let the wind come. Don't pull so straight."
So I let out the string, slow and slow,
and felt the gentle breezes blow.

The kite began to rise and climb,
up past the oak, one tug at a time.
The more I gave, the higher it went,
a small red dot, its tail unbent.

Now when I want things fast and right,
I think about that springtime kite.
Sometimes the way to help things soar
is holding on a little less, not more.$q$, 'draft')
