-- Passage rg4-theme-summary-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('b8cd23c7-8f06-531b-90ec-b1a57bae68c0', 'rg4-theme-summary-p06', (select id from public.skills where slug = 'read-g4-theme-summary'), null,
        '3-5', $q$The Story Quilt$q$, $q$Hana's grandmother kept a quilt folded at the foot of her bed. It was made of dozens of squares, and no two were alike. One rainy Saturday, Hana asked why the quilt looked so mixed up.

Grandma Sun-hee smiled and spread it across the bed. "Every square comes from someone in our family," she said.

She pointed to a pale yellow square. "This was your father's baby blanket." A square of blue denim had come from Grandpa's work shirt. He had worn it every day at the bus station where he fixed engines. A flowered square was cut from an apron. Hana's great-aunt wore it when she ran a small noodle shop.

Hana touched each square as her grandmother talked. She had never met her great-aunt. Now she could almost picture her stirring a big pot of noodles.

"There is still room for more," Grandma Sun-hee said. She showed Hana an empty corner.

Hana thought for a moment. Then she ran to her closet and came back with her old green team shirt. It was too small for her now. "Can this go in?" she asked.

Together they cut a square from the shirt. Grandma Sun-hee showed Hana how to make small, even stitches. It took the whole afternoon.

When they finished, Hana looked at the quilt again. Her green square sat right beside her father's yellow one.$q$, 'draft')
