-- Passage rg4-word-parts-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('8810dbb2-7977-552a-9fa2-57b075d92206', 'rg4-word-parts-p03', (select id from public.skills where slug = 'read-g4-word-parts'), null,
        '3-5', $q$The Author Visit$q$, $q$When the author Nadia Farrow visited Lakeview Elementary, Daniel brought his favorite book. He hoped to get her autograph on the first page.

Ms. Farrow read aloud from her newest story. Then she held up a photograph of the small town where she grew up. The houses were painted bright colors, and a river ran past the school.

Afterward, students lined up at a table. Daniel felt nervous. What if he said something silly? When it was his turn, Ms. Farrow smiled and asked his name. She wrote "To Daniel" in neat letters, and then she signed her own name below it.

"Do you like to write?" she asked. Daniel nodded. He told her he was writing a story about a fearless dog who rode a bicycle. Ms. Farrow laughed. "That sounds wonderful. Keep going," she said.

That night, Daniel reread his story from the beginning. He fixed a few spelling mistakes and added a new chapter. He decided he would become a writer someday, too.$q$, 'draft')
