-- Passage rg5-character-setting-plot-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('9cb513d8-cae6-58bb-8ca2-6f82639e83a9', 'rg5-character-setting-plot-p02', (select id from public.skills where slug = 'read-g5-character-setting-plot'), null,
        '3-5', $q$Two Mornings$q$, $q$In the city, morning comes in pieces.
A bus sighs at the corner.
A neighbor's door clicks shut.
The sun squeezes between two buildings
to lay one thin stripe across my bed.

At Abuela's house by the bay,
morning comes all at once.
The roosters argue with the gulls.
The whole sky turns orange over the water,
and light pours through the window like spilled juice.

In the city, I hurry.
I grab my toast and my backpack
and race the crossing light.

At Abuela's, nobody hurries.
We sit on the porch steps with warm bread
and watch the fishing boats slide out.

Both mornings are mine.
One teaches me to be quick,
and one teaches me to be still.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
