-- Passage rg5-character-setting-plot-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('3fc3dd75-bda6-507e-bc78-993282894856', 'rg5-character-setting-plot-p06', (select id from public.skills where slug = 'read-g5-character-setting-plot'), null,
        '3-5', $q$First Meet, Last Meet$q$, $q$In June, at my first swim meet,
my goggles fogged and my cap slid down.
The starting horn was so loud
I jumped in late.
I swam with my head up,
counting the flags,
and finished last by half a pool.

In August, at my last meet,
I tugged my cap down tight
and listened only for the horn.
I dove in flat and fast.
I breathed every third stroke,
the way Coach Ama taught,
and touched the wall in third place.

The pool was the same pool.
The water was just as cold.
The crowd cheered just as loud.
The swimmer was the one who changed.$q$, 'draft')
