-- Passage rg5-connections-p04
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('09bf0e03-6973-5491-99fe-0502f3718c78', 'rg5-connections-p04', (select id from public.skills where slug = 'read-g5-connections'), null,
        '3-5', $q$The Bookmobile Comes to Pine Hollow$q$, $q$Pine Hollow is a small farming town. The nearest public library is thirty miles away, in a bigger town. For years, many children in Pine Hollow rarely borrowed books, because their families could not make the long drive often.

Mrs. Adaeze Okafor, the county librarian, wanted to fix this. She asked the county board for money to buy a used delivery truck. Volunteers built shelves inside it and painted the outside bright blue. The truck became the county's first bookmobile.

Every other Tuesday, the bookmobile parks outside the Pine Hollow general store. Children climb aboard to return books and choose new ones. Mr. Tomas Reyes, the driver, also takes requests. If a child wants a book that is not on the truck, he brings it on the next visit.

The visits changed reading habits in town. The school's teacher, Ms. Hana Kim, noticed that her students began talking about books at lunch. Some children formed a club to share reading ideas. Because the club members wanted more books, they asked Mr. Reyes for extra copies of popular titles.

Last spring, the county board voted to buy a second bookmobile. Mrs. Okafor plans to send it to two other faraway towns. She says Pine Hollow showed her what a library on wheels can do.$q$, 'draft')
